import{_ as o,l as i,o as e,c as n,v as t,p as s,x as l,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"图表与表格理解","description":"","frontmatter":{"title":"图表与表格理解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/chart-table-understanding.md","filePath":"llm/chart-table-understanding.md","lastUpdated":1789023840000}'),c={name:"llm/chart-table-understanding.md"};function m(E,a,_,u,A,f){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="图表与表格理解" tabindex="-1">图表与表格理解 <a class="header-anchor" href="#图表与表格理解" aria-label="Permalink to &quot;图表与表格理解&quot;">​</a></h1><div class="epigraph"><p>柱的高度是几何，不是名词。把图当成场景描述，数轴与图例会先死在流畅的错答里。</p><footer>—— Masry 等 ChartQA；Liu 等 DePlot；文档侧对照 [OCR 与文档 VLM](/llm/ocr-vlm)</footer></div><p><a href="/llm/gui-grounding">上一课</a>读的是控件。<a href="/llm/ocr-vlm">OCR</a> 读的是字。缺口是把几何量译成数：轴刻度、图例颜色、柱高、单元格行列。后课长视频默认单帧结构已经能读，再加时间维。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ChartQA 一类题要看图作答，答案常是数或短短语。失败模式不是「没看见图」，而是：轴范围读错、把装饰当数据、图例颜色绑错系列、表格跨页对错列。强制 squish 的 <a href="/llm/vit-as-encoder">ViT</a> 会把细刻度糊进同一 patch；<a href="/llm/clip">CLIP</a> 标题先验会把常见图表故事写出来，与这张图的真实柱高无关。</p><p>DePlot 把图表先译成表（plot-to-table），再在表上推理，把视觉识别与算术拆开。端到端 VLM 则要求同一 <a href="/llm/llava-projector">投影器</a> 前缀同时支撑读刻度与计算。</p><p><span class="marginnote">表可以是图（扫描件）或已解析的 HTML/Markdown。本课管「当图像看的表」。已解析表应走文本，不要浪费视觉 token。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分辨率与长宽比优先：宽表用横条切格（<a href="/llm/anyres">AnyRes</a> 或原生分辨率）。监督要含：转写为 Markdown/CSV、读指定单元格、读轴上的值，而不只是「这是什么图」。算术应允许先抽取数字再算，避免口算与读图绑死。评测：ChartQA 等与纯 OCR、纯表格 QA 分列；检查「数对了但系列绑错」。</p>',9)),(e(),s(p,null,{default:l(()=>[h(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%9B%BE%E8%A1%A8%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20GEO%5B%22%E8%BD%B4%20%2F%20%E5%9B%BE%E4%BE%8B%20%2F%20%E5%87%A0%E4%BD%95%22%5D%0A%20%20GEO%20--%3E%20TAB%5B%22%E8%A1%A8%E6%88%96%E6%95%B0%E5%88%97%22%5D%0A%20%20TAB%20--%3E%20QA%5B%22%E9%97%AE%E7%AD%94%E4%B8%8E%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>读图是把像素几何逆映射到数据坐标：柱顶相对原点的比例 × 轴量程。这依赖格子仍分辨刻度线，以及模型把图例颜色当作键去查系列。语言先验提供的是「失业率图通常长这样」，不能提供这张图的读数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>抽取对了仍可能算错；算对了也可能看错系列。下一课把画布换成视频：结构问题变成时间采样与记忆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图表理解是几何到数字，不是场景描述。</li><li>先读成表再推理，可把识别与算术解耦。</li><li>分辨率与长宽比决定刻度是否还在。</li><li>出处：ChartQA；DePlot。</li></ul>',6))])}const b=o(c,[["render",m]]);export{T as __pageData,b as default};
